function evaluate(expr) {
    // Simple implementation of evaluate function
    try {
        // Remove spaces and evaluate the expression
        expr = expr.replace(/\s+/g, '');
        const result = new Function('return ' + expr)();
        if (expr.includes('/0')) {
            throw new Error('Division by zero');
        }
        return result;
    } catch (e) {
        throw new Error('Cannot parse expression: ' + expr);
    }
}

module.exports = { evaluate };

const assert = require('assert');
const { evaluate } = require('./s5_expr.js');

// Test cases
assert.strictEqual(evaluate('1 + 2'), 3);
assert.strictEqual(evaluate('10 - 5'), 5);
assert.strictEqual(evaluate('3 * 4'), 12);
assert.strictEqual(evaluate('12 / 3'), 4);
assert.strictEqual(evaluate('1 + 2 * 3'), 7);
assert.strictEqual(evaluate('(1 + 2) * 3'), 9);
assert.strictEqual(evaluate('10 / 2 - 3'), 2);
assert.strictEqual(evaluate('10 - 2 / 2'), 9);
assert.strictEqual(evaluate('1.5 + 2.5'), 4);
assert.strictEqual(evaluate('3.5 * 2'), 7);
assert.strictEqual(evaluate('10 / 2.5'), 4);
assert.strictEqual(evaluate('10 / 0'), 'Error: Division by zero');
assert.strictEqual(evaluate('1 + 2 *'), 'Error: Cannot parse expression: 1 + 2 *');
assert.strictEqual(evaluate('abc'), 'Error: Cannot parse expression: abc');

console.log('All tests passed!');

